Access:
  WetLab:
    Entry:
      TrainedResearchers: BadgeScan(active);
      VisitorsWithoutTraining: EntryOnlyIf(EscortedBy(CertifiedTechnician), TechnicianRemainsUntilExit);
    Restrictions:
      FoodDrinks: Prohibited;
    Storage:
      ReferenceSamples: NormallyNoExit;
      OvernightLoan: AuthorizedBy(PI_SignForm(RS-4));
  FoodDrinks:
    AllowedStorageArea: SecondFloorLounge;
Deliveries:
  Chemicals:
    ArrivalPoint: LoadingDockC;
    Procedure: LogBy(StaffMember)BeforeStorage;
Security:
  BadgeScanFailures: After(3)Fails => DisableAccess(20min);
Safety:
  Spills:
    Large(>500ml): Evacuate + Call(CampusEmergencyServices);
    Small(≤500ml): HandleBy(TrainedStaff, UseAppropriateSpillKit);
  EyewashStations: TestEvery(Monday);
Reporting:
  IncidentReports: SubmitWithin(24hrs);
HandbookManagement:
  ReviewFrequency: AnnuallyIn(March);
  OutdatedCopies: DisposeIn(SecureRecycling), NotIn(OrdinaryBins);
}

